'use client';

import React, { useMemo, useRef, useState } from 'react';
import { MapPin, Plus, Sparkles, X } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Region, regionsApi } from '@/features/regions/api';
import type { VenueOption } from '@/features/venues/api';
import type { TournamentVenueWithCourts } from '@/features/tournaments/api';
import { useAutoAddressParser } from '@/utils/vietnamAddressParser';

interface CreateVenueModalProps {
  isOpen: boolean;
  onClose: () => void;
  provinces: Region[];
  setWards?: (wards: Region[]) => void;
  /** Global catalog; attached venues are excluded from the selectable options. */
  venues?: VenueOption[];
  attachedVenues?: readonly Pick<TournamentVenueWithCourts, 'id'>[];
  onAttachExistingVenue?: (venueId: string) => Promise<void>;
  onCreateVenue: (data: {
    name: string;
    locationAddress: string;
    venueId?: string;
    isDefault?: boolean;
    initialCourtCount?: number;
    courtPrefix?: string;
  }) => Promise<void>;
}

export function CreateVenueModal({
  isOpen,
  onClose,
  provinces,
  setWards,
  venues = [],
  attachedVenues = [],
  onAttachExistingVenue,
  onCreateVenue,
}: CreateVenueModalProps) {
  const translate = useTranslations('OrganizerManage');
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [provinceCode, setProvinceCode] = useState('');
  const [wardCode, setWardCode] = useState('');
  const [availableWards, setAvailableWards] = useState<Region[]>([]);
  const [isLoadingWards, setIsLoadingWards] = useState(false);
  const [wardLoadError, setWardLoadError] = useState('');
  const [selectedExistingVenueId, setSelectedExistingVenueId] = useState('');
  const [isAttachingExisting, setIsAttachingExisting] = useState(false);
  const wardRequestIdRef = useRef(0);
  const [isDefault, setIsDefault] = useState(false);
  const [initialCourtCount, setInitialCourtCount] = useState(4);
  const [courtPrefix, setCourtPrefix] = useState('Sân');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const availableVenues = useMemo(() => {
    const attachedVenueIds = new Set(attachedVenues.map(({ id }) => id));
    return venues.filter((venue) => !attachedVenueIds.has(venue.id));
  }, [attachedVenues, venues]);

  const autoDetectedAddress = useAutoAddressParser({
    addressValue: address,
    provinces,
    wards: availableWards,
    onSelectProvince: setProvinceCode,
    onSelectWard: setWardCode,
    onWardsLoaded: (loadedWards) => {
      setAvailableWards(loadedWards);
      setWards?.(loadedWards);
    },
  });

  if (!isOpen) return null;

  const handleProvinceChange = async (provCode: string) => {
    const requestId = ++wardRequestIdRef.current;
    setProvinceCode(provCode);
    setWardCode('');
    setAvailableWards([]);
    setWardLoadError('');
    if (!provCode) {
      if (setWards) setWards([]);
      return;
    }
    setIsLoadingWards(true);
    try {
      // Keep this form on the same canonical region loader as tournament
      // creation. The province code, not the display label, is the API key.
      const res = await regionsApi.getWards(String(provCode).trim());
      if (requestId !== wardRequestIdRef.current) return;

      // The API is the single source of truth. An empty response means the
      // backend region data is incomplete and must be fixed there; do not
      // substitute another screen's ward list and risk showing wrong regions.
      const nextWards = Array.isArray(res) ? res : [];
      setAvailableWards(nextWards);
      setWards?.(nextWards);
      if (nextWards.length === 0) {
        setWardLoadError('Chưa có dữ liệu phường/xã cho tỉnh này. Bạn vẫn có thể nhập địa chỉ chi tiết.');
      }
    } catch {
      if (requestId !== wardRequestIdRef.current) return;
      setWardLoadError('Không tải được danh sách phường/xã. Bạn có thể thử lại.');
    } finally {
      if (requestId === wardRequestIdRef.current) setIsLoadingWards(false);
    }
  };

  const handleAttachExistingVenue = async () => {
    if (!selectedExistingVenueId || !onAttachExistingVenue) return;
    setIsAttachingExisting(true);
    try {
      await onAttachExistingVenue(selectedExistingVenueId);
      setSelectedExistingVenueId('');
      onClose();
    } finally {
      setIsAttachingExisting(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    const pName = provinces.find((p) => p.code === provinceCode)?.name || '';
    const wName = availableWards.find((w) => w.code === wardCode)?.name || '';
    const fullAddress = [address.trim(), wName, pName].filter(Boolean).join(', ') || address.trim();

    setIsSubmitting(true);
    try {
      await onCreateVenue({
        name: name.trim(),
        locationAddress: fullAddress,
        isDefault,
        initialCourtCount: initialCourtCount > 0 ? initialCourtCount : undefined,
        courtPrefix: courtPrefix.trim() || 'Sân',
      });
      setName('');
      setAddress('');
      setProvinceCode('');
      setWardCode('');
      setAvailableWards([]);
      setWardLoadError('');
      setSelectedExistingVenueId('');
      onClose();
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-xs animate-in fade-in duration-150">
      <div className="relative w-full max-w-lg rounded-xl bg-white shadow-xl border border-slate-200 overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4 bg-white">
          <div className="flex items-center gap-2.5">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-blue-50 text-blue-600 border border-blue-100">
              <MapPin className="h-4 w-4" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">Thêm địa điểm thi đấu</h3>
              <p className="text-xs text-slate-500">Tạo thêm cụm sân hoặc địa điểm tổ chức thi đấu</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-700 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-5 space-y-4 max-h-[80vh] overflow-y-auto">
          {availableVenues.length > 0 && (
            <div className="rounded-lg border border-blue-100 bg-blue-50/60 p-3.5 space-y-2.5">
              <div>
                <p className="text-xs font-bold text-slate-800">{translate('savedVenueTitle')}</p>
                <p className="mt-0.5 text-xs text-slate-500">{translate('savedVenueHint')}</p>
              </div>
              <select
                value={selectedExistingVenueId}
                onChange={(event) => setSelectedExistingVenueId(event.target.value)}
                className="w-full h-10 rounded-lg border border-slate-300 bg-white px-3 text-xs text-slate-800 focus:border-blue-500 focus:outline-hidden"
              >
                <option value="">{translate('savedVenuePlaceholder')}</option>
                {availableVenues.map((venue) => (
                  <option key={venue.id} value={venue.id}>
                    {venue.name} — {venue.locationAddress || 'Chưa có địa chỉ'}
                  </option>
                ))}
              </select>
              {selectedExistingVenueId && (
                <Button
                  type="button"
                  onClick={() => void handleAttachExistingVenue()}
                  disabled={isAttachingExisting}
                  className="h-9 w-full bg-blue-600 hover:bg-blue-700 text-white text-xs font-semibold rounded-lg"
                >
                  {isAttachingExisting ? translate('attachingSavedVenue') : translate('attachSavedVenue')}
                </Button>
              )}
            </div>
          )}

          <div className="border-t border-slate-100 pt-1">
            <p className="text-xs font-bold text-slate-800">Tạo địa điểm mới</p>
          </div>

          {/* Venue Name */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">
              Tên địa điểm / Tên CLB <span className="text-rose-500">*</span>
            </label>
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="VD: CLB Cầu Lông Kỳ Hòa, Sân Pickleball Hồ Bơi..."
              className="h-10 text-xs rounded-lg border-slate-300"
              required
            />
          </div>

          {/* Address */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">
              Địa chỉ chi tiết <span className="text-rose-500">*</span>
            </label>
            <Input
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              placeholder="VD: 123 Lê Lợi, Phường Bến Nghé, Quận 1..."
              className="h-10 text-xs rounded-lg border-slate-300"
              required
            />
            {autoDetectedAddress.isMatched && (autoDetectedAddress.province || autoDetectedAddress.ward) && (
              <p className="mt-1 text-xs text-emerald-600 flex items-center gap-1 font-medium">
                <Sparkles className="h-3 w-3" />
                Tự động nhận diện: {[autoDetectedAddress.ward?.name, autoDetectedAddress.province?.name].filter(Boolean).join(', ')}
              </p>
            )}
          </div>

          {/* Provinces / Wards */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Tỉnh / Thành phố</label>
              <select
                value={provinceCode}
                onChange={(e) => handleProvinceChange(e.target.value)}
                className="w-full h-10 rounded-lg border border-slate-300 bg-white px-3 text-xs text-slate-800 focus:border-blue-500 focus:outline-hidden"
              >
                <option value="">-- Chọn Tỉnh / Thành phố --</option>
                {provinces.map((p) => (
                  <option key={p.code} value={p.code}>
                    {p.name}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Phường / Xã</label>
              <select
                value={wardCode}
                onChange={(e) => setWardCode(e.target.value)}
                disabled={!provinceCode || isLoadingWards}
                className="w-full h-10 rounded-lg border border-slate-300 bg-white px-3 text-xs text-slate-800 focus:border-blue-500 focus:outline-hidden disabled:bg-slate-100 disabled:text-slate-400"
              >
                <option value="">
                  {!provinceCode
                    ? '-- Chọn Tỉnh / Thành phố trước --'
                    : isLoadingWards
                      ? 'Đang tải phường / xã...'
                      : '-- Chọn Phường / Xã --'}
                </option>
                {availableWards.map((w) => (
                  <option key={w.code} value={w.code}>
                    {w.name}
                  </option>
                ))}
              </select>
              {wardLoadError && (
                <div className="mt-1 flex items-center justify-between gap-2 text-xs text-rose-600">
                  <span>{wardLoadError}</span>
                  <button
                    type="button"
                    onClick={() => void handleProvinceChange(provinceCode)}
                    className="shrink-0 font-semibold underline underline-offset-2"
                  >
                    Thử lại
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* Initial Courts Generator */}

