content.text:
  const filteredParticipants = useMemo(
    () => selectableParticipants.filter((participant) => {
      const normalizedName = getParticipantName(participant)
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLocaleLowerCase()
        .replace(/đ/g, 'd');
      return normalizedName.includes(normalizedQuery);
    }),
    [normalizedQuery, selectableParticipants],
  );

  // Reopening the picker must never resurrect a previous run's confirmation or
  // notice. This resets during render — the same derived-state pattern the brand
  // avatars already use — so a closed modal never reads stale state back and the
  // reset costs no extra commit the way an effect would.
  const [wasOpen, setWasOpen] = useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (!open) {
      setIsConfirmingRandom(false);
      setShowRandomNoPairsNotice(false);
    }
  }

  useEffect(() => {
    if (isConfirmingRandom) randomConfirmRef.current?.focus();
  }, [isConfirmingRandom]);

  useEffect(() => {
    if (isConfirmingRandom || !listRef.current) return;
    listRef.current.scrollTop = savedListScrollTopRef.current;
  }, [isConfirmingRandom]);

  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen && isPairing) return;
    if (!nextOpen) {
      setQuery('');
      setSelectedIds([]);
      setTeamName('');
      setIsConfirmingRandom(false);
      setShowRandomNoPairsNotice(false);
    }
    onOpenChange(nextOpen);
  };

  // Step 1 discloses the scope and sends nothing.
  const openRandomConfirmation = () => {
    if (isLoading || isPairing) return;
    savedListScrollTopRef.current = listRef.current?.scrollTop ?? 0;
    setShowRandomNoPairsNotice(false);
    setIsConfirmingRandom(true);
  };

  // Step 1's escape hatch: closes the confirmation only, leaving the picker,
  // the search term and the selection untouched.
  const closeRandomConfirmation = () => {
    if (isPairing) return;
    setIsConfirmingRandom(false);
  };

  const handleConfirmKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== 'Escape' || isPairing) return;
    event.preventDefault();
    event.stopPropagation();
    setIsConfirmingRandom(false);
  };

  // Step 2 is the only control that issues the tournament-wide request.
  const handleConfirmRandomPairing = async () => {
    if (isPairing) return;
    const outcome = await onGenerateRandomPairs();
    setIsConfirmingRandom(false);
    if (outcome === 'formed') {
      setQuery('');
      setSelectedIds([]);
      setTeamName('');
      return;
    }
    setShowRandomNoPairsNotice(outcome === 'none');
  };

  const handlePair = async () => {
    const [participant1Id, participant2Id] = selectedIds;
    if (!participant1Id || !participant2Id) return;
    const cleanTeamName = teamName.trim();
    const paired = await onPair({
      participant1Id,
      participant2Id,
      ...(cleanTeamName ? { teamName: cleanTeamName } : {}),
    });
    if (paired) {
      setQuery('');
      setSelectedIds([]);
      setTeamName('');
    }
  };

  const canPair = selectedIds.length === 2 && !isLoading && !isPairing;

  return (
    <Modal open={open} onOpenChange={handleOpenChange}>
      <ModalContent className="max-h-[90vh] max-w-xl overflow-hidden bg-white p-0">
        <ModalHeader className="border-b border-slate-200 px-5 py-4 text-left">
          <ModalTitle className="flex items-center gap-2 text-lg font-bold text-slate-900">
            <Users aria-hidden="true" className="h-5 w-5 text-blue-600" />
            {translate('pairingDialogTitle')}
          </ModalTitle>
          <ModalDescription className="text-sm text-slate-600">
            {translate('pairingDialogDescription', { division: divisionName ? ` — ${divisionName}` : '' })}
            {selectedIds.length === 1 && (
              <span className="mt-1 block">{translate('pairingSameDivisionHint')}</span>
            )}
          </ModalDescription>
        </ModalHeader>

        {isConfirmingRandom ? (
          <div
            ref={randomConfirmRef}
            role="dialog"
            aria-labelledby={randomConfirmTitleId}
            aria-describedby={randomConfirmDescriptionId}
            tabIndex={-1}
            onKeyDown={handleConfirmKeyDown}
            className="space-y-4 p-5 focus-visible:outline-none"
          >
            <h3 id={randomConfirmTitleId} className="text-base font-bold text-slate-900">
              {translate('pairingRandomConfirmTitle')}
            </h3>
            <p id={randomConfirmDescriptionId} className="text-sm leading-relaxed text-slate-600">
              {translate('pairingRandomConfirmDescription')}
            </p>
            <div className="flex flex-col-reverse gap-2 border-t border-slate-100 pt-4 sm:flex-row sm:justify-end">
              <Button type="button" variant="outline" disabled={isPairing} onClick={closeRandomConfirmation}>
                {translate('pairingCancel')}
              </Button>
              <Button type="button" disabled={isPairing} isLoading={isPairing} onClick={() => void handleConfirmRandomPairing()}>
                {isPairing ? translate('pairingRunning') : translate('pairingRandomConfirmAction')}
              </Button>
            </div>
          </div>
        ) : (
          <div className="space-y-4 p-5">
            {showRandomNoPairsNotice && (
              <p
                role="status"
                className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-medium text-amber-900"
              >
                {translate('pairingNoPairsFormed')}
              </p>
            )}

…
          </div>
        )}
      </ModalContent>
    </Modal>
  );

