'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { getFacebookShareUrl, getZaloShareUrl, getMessengerShareUrl } from '@/utils/share.util';
import toast from 'react-hot-toast';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
  shareUrl: string;
  title: string;
  shareText?: string;
  fbAppId?: string; // Optional Facebook App ID
}

export default function ShareModal({ isOpen, onClose, shareUrl, title, shareText, fbAppId }: ShareModalProps) {
  const effectiveShareText = shareText || title;
  const [copied, setCopied] = useState(false);
  const translate = useTranslations('Common');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 0);
    return () => clearTimeout(timer);
  }, []);

  const supportNativeShare = mounted && typeof navigator !== 'undefined' && typeof navigator.share === 'function';

  // Khóa cuộn trang khi Modal mở
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      toast.success(translate('shareCopied'));
      setTimeout(() => setCopied(false), 2000); // Reset trạng thái sau 2s
    } catch (err) {
      console.error('Sao chép liên kết thất bại:', err);
    }
  };

  const openSharePopup = (url: string) => {
    const width = 600;
    const height = 450;
    const left = window.screen.width / 2 - width / 2;
    const top = window.screen.height / 2 - height / 2;
    window.open(
      url,
      'share-dialog',
      `width=${width},height=${height},left=${left},top=${top},location=no,toolbar=no,menubar=no`
    );
  };

  const handleInstagramShare = () => {
    try {
      navigator.clipboard.writeText(shareUrl);
      toast.success(translate('instagramCopied'));
      setTimeout(() => {
        window.open('https://instagram.com', '_blank');
      }, 800);
    } catch (err) {
      window.open('https://instagram.com', '_blank');
    }
  };

  const handleNativeShare = async () => {
    try {
      await navigator.share({
        title: title,
        text: effectiveShareText,
        url: shareUrl,
      });
    } catch (err) {
      console.log('Native share failed or dismissed', err);
    }
  };

  // URL generators
  const getTwitterShareUrl = (url: string, text: string) => 
    `https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;

  const getThreadsShareUrl = (url: string, text: string) => 
    `https://threads.net/intent/post?text=${encodeURIComponent(text + ' ' + url)}`;

  const getTelegramShareUrl = (url: string, text: string) => 
    `https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Background Overlay */}
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-[3px] transition-opacity duration-350"
        onClick={onClose}
      />

      {/* Modal Card */}
      <div className="relative w-full max-w-lg overflow-hidden rounded-lg border border-slate-100 bg-white p-6 text-slate-900 shadow-2xl transition-all duration-300 transform scale-100 mx-4">

        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-100 pb-4">
          <h3 className="text-lg font-semibold tracking-tight text-slate-950">{translate('shareTitle')}</h3>
          <button 
            onClick={onClose}
            className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-100 text-slate-550 transition-all hover:bg-slate-200/70 hover:text-slate-800 cursor-pointer"
          >
            ✕
          </button>
        </div>

        {/* Info Title */}
        <div className="mt-4">
          <p className="text-xs font-medium text-slate-500 leading-relaxed">
             {translate('shareDescription', { title })}
          </p>
        </div>

        {/* Social Action Grid */}
        <div className="mt-5 grid grid-cols-4 gap-2.5">
          {/* Zalo */}
          <button
            onClick={() => openSharePopup(getZaloShareUrl(shareUrl))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-blue-200 hover:bg-blue-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#0068ff] font-bold text-white text-xs transition-all group-hover:scale-105 shadow-sm">
              Zalo
            </div>
            <span className="text-xs font-semibold text-slate-700">Zalo</span>
          </button>

          {/* Facebook */}
          <button
            onClick={() => openSharePopup(getFacebookShareUrl(shareUrl))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-blue-300 hover:bg-blue-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#1877f2] text-white transition-all group-hover:scale-105 shadow-sm">
              <svg className="h-4 w-4 fill-current" viewBox="0 0 24 24">
                <path d="M9 8h-3v4h3v12h5v-12h3.642l.358-4h-4v-1.667c0-.955.192-1.333 1.115-1.333h2.885v-5h-3.808c-3.596 0-5.192 1.583-5.192 4.615v3.385z"/>
              </svg>
            </div>
            <span className="text-xs font-semibold text-slate-700">Facebook</span>
          </button>

          {/* Messenger */}
          <button
            onClick={() => openSharePopup(getMessengerShareUrl(shareUrl, fbAppId))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-pink-200 hover:bg-pink-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-tr from-blue-500 via-purple-500 to-pink-500 text-white transition-all group-hover:scale-105 shadow-sm">
              <svg className="h-4.5 w-4.5 fill-current" viewBox="0 0 24 24">
                <path d="M12 2C6.477 2 2 6.145 2 11.243a8.97 8.97 0 003.582 7.084V22l3.528-1.938A10.457 10.457 0 0012 20.485c5.523 0 10-4.146 10-9.242C22 6.145 17.523 2 12 2zm1.06 12.029l-2.613-2.784-5.1 2.784 5.61-5.955 2.613 2.784 5.1-2.784z"/>
              </svg>
            </div>
            <span className="text-xs font-semibold text-slate-700">Messenger</span>
          </button>

          {/* Telegram */}
          <button
            onClick={() => openSharePopup(getTelegramShareUrl(shareUrl, effectiveShareText))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-blue-200 hover:bg-blue-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#229ED9] text-white transition-all group-hover:scale-105 shadow-sm">
              <svg className="h-4.5 w-4.5 fill-current" viewBox="0 0 24 24">
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm4.64 6.8c-.15 1.58-.8 5.42-1.13 7.19-.14.75-.42 1-.68 1.03-.58.05-1.02-.38-1.58-.75-.88-.58-1.38-.94-2.23-1.5-.99-.65-.35-1.01.22-1.59.15-.15 2.71-2.48 2.76-2.69.01-.03.01-.14-.07-.2-.08-.06-.19-.04-.27-.02-.11.02-1.93 1.23-5.46 3.62-.51.35-.98.53-1.39.51-.46-.01-1.35-.26-2.01-.48-.81-.27-1.46-.42-1.4-.88.03-.24.37-.49 1.02-.75 3.99-1.74 6.66-2.88 8.01-3.43 3.81-1.56 4.6-.1.08.3z"/>
              </svg>
            </div>
            <span className="text-xs font-semibold text-slate-700">Telegram</span>
          </button>

          {/* Twitter (X) */}
          <button
            onClick={() => openSharePopup(getTwitterShareUrl(shareUrl, effectiveShareText))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-slate-300 hover:bg-slate-50 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-slate-900 text-white transition-all group-hover:scale-105 shadow-sm">
              <svg className="h-3.5 w-3.5 fill-current" viewBox="0 0 24 24">
                <path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/>
              </svg>
            </div>
            <span className="text-xs font-semibold text-slate-700">Twitter X</span>
          </button>

          {/* Threads */}
          <button
            onClick={() => openSharePopup(getThreadsShareUrl(shareUrl, effectiveShareText))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-slate-300 hover:bg-slate-50 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-slate-900 text-white transition-all group-hover:scale-105 shadow-sm">
              <span className="font-bold text-[12px] italic tracking-tight">Th.</span>
            </div>
            <span className="text-xs font-semibold text-slate-700">Threads</span>
          </button>

          {/* Instagram */}
          <button
            onClick={handleInstagramShare}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-pink-200 hover:bg-pink-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-tr from-yellow-500 via-red-500 to-purple-500 text-white transition-all group-hover:scale-105 shadow-sm">
              <svg className="h-4.5 w-4.5 fill-current" viewBox="0 0 24 24">
