'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { getFacebookShareUrl, getZaloShareUrl, getMessengerShareUrl } from '@/utils/share.util';
import toast from 'react-hot-toast';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
  shareUrl: string;
  title: string;
  shareText?: string;
  fbAppId?: string; // Optional Facebook App ID
}

export default function ShareModal({ isOpen, onClose, shareUrl, title, shareText, fbAppId }: ShareModalProps) {
  const effectiveShareText = shareText || title;
  const [copied, setCopied] = useState(false);
  const translate = useTranslations('Common');
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 0);
    return () => clearTimeout(timer);
  }, []);

  const supportNativeShare = mounted && typeof navigator !== 'undefined' && typeof navigator.share === 'function';

  // Khóa cuộn trang khi Modal mở
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      toast.success(translate('shareCopied'));
      setTimeout(() => setCopied(false), 2000); // Reset trạng thái sau 2s
    } catch (err) {
      console.error('Sao chép liên kết thất bại:', err);
    }
  };

  const openSharePopup = (url: string) => {
    const width = 600;
    const height = 450;
    const left = window.screen.width / 2 - width / 2;
    const top = window.screen.height / 2 - height / 2;
    window.open(
      url,
      'share-dialog',
      `width=${width},height=${height},left=${left},top=${top},location=no,toolbar=no,menubar=no`
    );
  };

  const handleInstagramShare = () => {
    try {
      navigator.clipboard.writeText(shareUrl);
      toast.success(translate('instagramCopied'));
      setTimeout(() => {
        window.open('https://instagram.com', '_blank');
      }, 800);
    } catch (err) {
      window.open('https://instagram.com', '_blank');
    }
  };

  const handleNativeShare = async () => {
    try {
      await navigator.share({
        title: title,
        text: effectiveShareText,
        url: shareUrl,
      });
    } catch (err) {
      console.log('Native share failed or dismissed', err);
    }
  };

  // URL generators
  const getTwitterShareUrl = (url: string, text: string) => 
    `https://twitter.com/intent/tweet?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;

  const getThreadsShareUrl = (url: string, text: string) => 
    `https://threads.net/intent/post?text=${encodeURIComponent(text + ' ' + url)}`;

  const getTelegramShareUrl = (url: string, text: string) => 
    `https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Background Overlay */}
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-[3px] transition-opacity duration-350"
        onClick={onClose}
      />

      {/* Modal Card */}
      <div className="relative w-full max-w-lg overflow-hidden rounded-lg border border-slate-100 bg-white p-6 text-slate-900 shadow-2xl transition-all duration-300 transform scale-100 mx-4">

        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-100 pb-4">
          <h3 className="text-lg font-semibold tracking-tight text-slate-950">{translate('shareTitle')}</h3>
          <button 
            onClick={onClose}
            className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-100 text-slate-550 transition-all hover:bg-slate-200/70 hover:text-slate-800 cursor-pointer"
          >
            ✕
          </button>
        </div>

        {/* Info Title */}
        <div className="mt-4">
          <p className="text-xs font-medium text-slate-500 leading-relaxed">
             {translate('shareDescription', { title })}
          </p>
        </div>

        {/* Social Action Grid */}
        <div className="mt-5 grid grid-cols-4 gap-2.5">
          {/* Zalo */}
          <button
            onClick={() => openSharePopup(getZaloShareUrl(shareUrl))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-blue-200 hover:bg-blue-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#0068ff] font-bold text-white text-xs transition-all group-hover:scale-105 shadow-sm">
              Zalo
            </div>
            <span className="text-xs font-semibold text-slate-700">Zalo</span>
          </button>

          {/* Facebook */}
          <button
            onClick={() => openSharePopup(getFacebookShareUrl(shareUrl))}
            className="flex flex-col items-center justify-center gap-2 rounded-lg border border-slate-100 bg-slate-50/60 py-3.5 px-1.5 transition-all hover:-translate-y-0.5 hover:border-blue-300 hover:bg-blue-50/30 group cursor-pointer"
          >
            <div className="flex h-9 w-9 items-center justify-center rounded-full bg-[#1877f2] text-white transition-all group-hover:scale-105 shadow-sm">
              <svg className="h-4 w-4 fill-current" viewBox="0 0 24 24">
